fn is_hidden(path: &Path) -> bool {
    if let Some(name) = path.file_name().and_then(|s| s.to_str()) {
        name.starts_with('.')
    } else {
        false
    }
}

fn should_use_color(mode: &ColorMode) -> bool {
    match mode {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => {
            // Check if stdout is tty
            // Use is_terminal
            std::io::IsTerminal::is_terminal(&std::io::stdout())
        }
    }
}

fn colorize(s: &str, code: &str, use_color: bool) -> String {
    if use_color {
        format!("\x1b[{}m{}\x1b[0m", code, s)
    } else {
        s.to_string()
    }
}

fn color_grey(s: &str, use_color: bool) -> String {
    if use_color {
        format!("\x1b[38;5;8m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}

fn color_green(s: &str, use_color: bool) -> String {
    colorize(s, "32", use_color)
}
fn color_red_bold(s: &str, use_color: bool) -> String {
    colorize(s, "1;31", use_color)
}
fn color_red(s: &str, use_color: bool) -> String {
    colorize(s, "31", use_color)
}
fn color_bold(s: &str, use_color: bool) -> String {
