fn backup_file(src: &Path) -> io::Result<PathBuf> {
    // Create backup file with .bk extension, incrementing if exists
    let src_str = src.to_string_lossy();
    let mut backup_path = PathBuf::from(format!("{}.bk", src_str));
    if !backup_path.exists() {
        // copy
        if src.is_dir() {
            // For dirs, maybe not backup? Original didn't backup dirs (we saw earlier backup for dir didn't create file). Let's skip dir backup? But let's attempt to copy dir recursively? Original seemed to not create backup for directories.
            // We will only backup files.
            // If src is dir, we won't backup? But spec says backup before renaming. Could be for files only.
            // We'll return error? Let's just not backup dirs.
            return Ok(backup_path);
        } else {
            fs::copy(src, &backup_path)?;
        }
        return Ok(backup_path);
    }
    let mut idx = 1;
    loop {
        let candidate = PathBuf::from(format!("{}.bk.{}", src_str, idx));
        if !candidate.exists() {
            if src.is_dir() {
                return Ok(candidate);
            } else {
                fs::copy(src, &candidate)?;
            }
            return Ok(candidate);
        }
        idx += 1;
    }
}

