fn apply_regex(old_name: &str, regex: &Regex, replacement: &str, limit: usize, transform: Option<&Transform>) -> Option<String> {
    // Returns new name if changed, else None
    // limit: 0 means unlimited
    // Transform: applied to the replacement result?

    // First, we need to check if regex matches old_name
    // Use regex.replace or replacen
    let new_name = if limit == 0 {
        // unlimited
        let result = regex.replace_all(old_name, replacement);
        result.to_string()
    } else if limit == 1 {
        // default: only first occurrence
        let result = regex.replace(old_name, replacement);
        result.to_string()
    } else {
        let result = regex.replacen(old_name, limit, replacement);
        result.to_string()
    };

    if new_name == old_name {
        return None;
    }

    // Apply transform if any
    let transformed = if let Some(t) = transform {
        match t {
            Transform::Upper => new_name.to_uppercase(),
            Transform::Lower => new_name.to_lowercase(),
            Transform::Ascii => deunicode::deunicode(&new_name),
        }
    } else {
        new_name
    };

    if transformed == old_name {
        None
    } else {
        Some(transformed)
    }
}

fn ascii_transform(name: &str) -> Option<String> {
    let ascii = deunicode::deunicode(name);
    if ascii == name {
        None
    } else {
        Some(ascii)
    }
}

