            std::process::exit(1);
        }
    }
    {
        use std::collections::HashMap;
        let mut map: HashMap<PathBuf, Vec<&RenameOp>> = HashMap::new();
        for op in &ops {
            map.entry(op.target.clone()).or_default().push(op);
        }
        for (target, srcs) in map {
            if srcs.len() > 1 {
                if !silent {
                    if use_color {
                        eprintln!("{}Files will have the same name", color_red("Error: ", use_color));
                        for s in srcs {
                            eprintln!("{}", color_red(&format!("{}->{}", s.source.display(), s.target.display()), use_color));
                        }
                    } else {
                        eprintln!("Error: Files will have the same name\n");
                        for s in &srcs {
                            eprintln!("{}->{}", s.source.display(), s.target.display());
                        }
                        eprintln!("");
                    }
                }
                std::process::exit(1);
            }
        }
    }

    ops.sort_by(|a, b| {
        let da = a.source.components().count();
        let db = b.source.components().count();
        db.cmp(&da)
    });

    for op in &ops {
        if args.common.backup && args.common.force {
            match backup_file(&op.source) {
                Ok(bp) => {
                    if !silent {
                        if use_color {
                            println!("{}Backup created - {}", color_bold("Info: ", use_color), color_grey(&format!("{} -> {}", op.source.display(), bp.display()), use_color));
                        } else {
                            print_backup_info_plain(&op.source.to_string_lossy(), &bp.to_string_lossy());
                        }
                    }
                }
                Err(e) => {
                    eprintln!("Error: Cannot create backup {}: {}", op.source.display(), e);
                    std::process::exit(1);
                }
            }
        }
        print_operation(&op.source.to_string_lossy(), &op.target.to_string_lossy(), &op.old_name, &op.new_name, silent, use_color);
        if args.common.force {
            if let Err(e) = fs::rename(&op.source, &op.target) {
                eprintln!("Error: Cannot rename {} -> {}\n{}", op.source.display(), op.target.display(), e);
                std::process::exit(1);
            }
        }
    }

    let should_dump = if args.common.no_dump {
        false
    } else if args.common.dump {
        true
    } else if args.common.force {
        true
    } else {
        false
    };

    if should_dump && !ops.is_empty() {
        let date = Local::now();
        let date_str = date.format("%Y-%m-%d %H:%M:%S").to_string();
        let file_date_str = date.format("%Y-%m-%d_%H%M%S").to_string();
        let dump_filename = format!("{}{}.json", args.common.dump_prefix, file_date_str);
        let dump_ops: Vec<Operation> = ops.iter().map(|op| Operation {
            source: op.source.to_string_lossy().to_string(),
            target: op.target.to_string_lossy().to_string(),
        }).collect();
        let dump = DumpFile {
            date: date_str,
            operations: dump_ops,
        };
        let json = serde_json::to_string_pretty(&dump).unwrap();
        if let Err(e) = fs::write(&dump_filename, json) {
            eprintln!("Error: Cannot write dump file {}: {}", dump_filename, e);
            std::process::exit(1);
        }
    }
}

fn handle_from_file(args: FromFileArgs) {
    let use_color = should_use_color(&args.common.color);
    let silent = args.common.silent;

    // Read dump file
    let content = match fs::read_to_string(&args.dumpfile) {
        Ok(c) => c,
        Err(_) => {
            let msg = format!("Error: Cannot open/read file {}", args.dumpfile.display());
            if use_color {
                // Need to check color for this error: earlier we saw DRY-RUN header then error?
                // For from-file, dry-run header is printed before error?
                // In earlier test, from-file nonexistent gave "This is a DRY-RUN" then error.
                // So print header first?
                if !args.common.force {
                    print_dry_run_header(silent, use_color);
                }
                eprintln!("{}{}", color_red("Error: ", use_color), color_red(&format!("Cannot open/read file {}", args.dumpfile.display()), use_color));
            } else {
                if !args.common.force {
                    print_dry_run_header(silent, use_color);
                }
                eprintln!("{}", msg);
            }
            std::process::exit(1);
        }
    };

    let dump: DumpFile = match serde_json::from_str(&content) {
        Ok(d) => d,
        Err(_) => {
            let msg = format!("Error: Cannot parse JSON file {}", args.dumpfile.display());
            if !args.common.force {
                print_dry_run_header(silent, use_color);
            }
            if use_color {
                eprintln!("{}{}", color_red("Error: ", use_color), format!("Cannot parse JSON file {}", args.dumpfile.display()));
            } else {
                eprintln!("{}", msg);
            }
            std::process::exit(1);
        }
    };

    let is_dry_run = !args.common.force;
    if is_dry_run {
        print_dry_run_header(silent, use_color);
    }

    // Build ops
    let mut ops: Vec<RenameOp> = Vec::new();
    for op in dump.operations {
        let (src, tgt) = if args.undo {
            (PathBuf::from(op.target), PathBuf::from(op.source))
        } else {
            (PathBuf::from(op.source), PathBuf::from(op.target))
        };
        // old_name and new_name are file names
        let old_name = src.file_name().and_then(|s| s.to_str()).unwrap_or("").to_string();
        let new_name = tgt.file_name().and_then(|s| s.to_str()).unwrap_or("").to_string();
        ops.push(RenameOp {
            source: src,
            target: tgt,
            old_name,
            new_name,
        });
    }

    // Conflict detection similar: existing path, same target
    for op in &ops {
        if op.target.exists() && op.source != op.target {
            // But if undoing, target is original source, which might exist? Actually after rename, original source should not exist, target (original) should not exist if file was renamed? Wait: if we rename file.txt->doc.txt, then file.txt no longer exists, doc.txt exists. If we try to undo without having doc.txt? Hmm.
            // For conflict, if target exists, error.
            let msg = format!("Error: Conflict with existing path {} -> {}", op.source.display(), op.target.display());
            if use_color {
                eprintln!("{}Conflict with existing path {}", color_red("Error: ", use_color), color_red(&format!("{} -> {}", op.source.display(), op.target.display()), use_color));
            } else {
                eprintln!("{}", msg);
            }
            std::process::exit(1);
        }
    }
    {
        use std::collections::HashMap;
        let mut map: HashMap<PathBuf, Vec<&RenameOp>> = HashMap::new();
        for op in &ops {
            map.entry(op.target.clone()).or_default().push(op);
        }
        for (_target, srcs) in map {
            if srcs.len() > 1 {
                if use_color {
                    eprintln!("{}Files will have the same name", color_red("Error: ", use_color));
                    for s in srcs {
                        eprintln!("{}", color_red(&format!("{}->{}", s.source.display(), s.target.display()), use_color));
                    }
                } else {
                    eprintln!("Error: Files will have the same name\n");
                    for s in &srcs {
                        eprintln!("{}->{}", s.source.display(), s.target.display());
                    }
                    eprintln!("");
                }
                std::process::exit(1);
            }
        }
    }

    // Sort deepest first
    ops.sort_by(|a, b| {
        let da = a.source.components().count();
        let db = b.source.components().count();
        db.cmp(&da)
    });

    for op in &ops {
        // Backup
        if args.common.backup && args.common.force {
            match backup_file(&op.source) {
                Ok(bp) => {
                    if !silent {
                        if use_color {
                            println!("{}Backup created - {}", color_bold("Info: ", use_color), color_grey(&format!("{} -> {}", op.source.display(), bp.display()), use_color));
                        } else {
                            print_backup_info_plain(&op.source.to_string_lossy(), &bp.to_string_lossy());
                        }
                    }
                }
                Err(e) => {
                    eprintln!("Error: Cannot create backup {}: {}", op.source.display(), e);
                    std::process::exit(1);
                }
            }
        }

        print_operation(&op.source.to_string_lossy(), &op.target.to_string_lossy(), &op.old_name, &op.new_name, silent, use_color);

        if args.common.force {
            if let Err(e) = fs::rename(&op.source, &op.target) {
                eprintln!("Error: Cannot rename {} -> {}\n{}", op.source.display(), op.target.display(), e);
                std::process::exit(1);
            }
        }
    }

    let should_dump = if args.common.no_dump {
        false
    } else if args.common.dump {
        true
    } else if args.common.force {
        true
    } else {
        false
    };

    if should_dump && !ops.is_empty() {
        let date = Local::now();
        let date_str = date.format("%Y-%m-%d %H:%M:%S").to_string();
        let file_date_str = date.format("%Y-%m-%d_%H%M%S").to_string();
        let dump_filename = format!("{}{}.json", args.common.dump_prefix, file_date_str);
        let dump_ops: Vec<Operation> = ops.iter().map(|op| Operation {
            source: op.source.to_string_lossy().to_string(),
            target: op.target.to_string_lossy().to_string(),
        }).collect();
        let dump_file = DumpFile {
            date: date_str,
            operations: dump_ops,
        };
        let json = serde_json::to_string_pretty(&dump_file).unwrap();
        if let Err(e) = fs::write(&dump_filename, json) {
            eprintln!("Error: Cannot write dump file {}: {}", dump_filename, e);
            std::process::exit(1);
        }
    }
}
