fn compute_target_colored_grouped(old: &str, new: &str, use_color: bool) -> String {
    if !use_color {
        return new.to_string();
    }
    // Try to group consecutive same tags to avoid many resets? But original resets after each segment, even if consecutive same color, it seems they combined? Let's see earlier: for ababa example, they had red, green, red, green, red, green - each segment single char but separated. If we group consecutive same tags, we'd have same.
    // However for "doc-123.log.txt" example, they had green "123." as one segment (4 chars) grouped. So grouping consecutive same tags works.
    use similar::{ChangeTag, TextDiff};
    let diff = TextDiff::from_chars(old, new);
    let mut out = String::new();
    let mut current_tag: Option<ChangeTag> = None;
    let mut buffer = String::new();
    for change in diff.iter_all_changes() {
        match change.tag() {
            ChangeTag::Equal => {
                if current_tag != Some(ChangeTag::Equal) {
                    if !buffer.is_empty() {
                        // flush
                        match current_tag {
                            Some(ChangeTag::Equal) => out.push_str(&color_green(&buffer, true)),
                            Some(ChangeTag::Insert) => out.push_str(&color_red_bold(&buffer, true)),
                            _ => out.push_str(&buffer),
                        }
                        buffer.clear();
                    }
                    current_tag = Some(ChangeTag::Equal);
                }
                buffer.push_str(&change.value().to_string());
            }
            ChangeTag::Insert => {
                if current_tag != Some(ChangeTag::Insert) {
                    if !buffer.is_empty() {
                        match current_tag {
                            Some(ChangeTag::Equal) => out.push_str(&color_green(&buffer, true)),
                            Some(ChangeTag::Insert) => out.push_str(&color_red_bold(&buffer, true)),
                            _ => out.push_str(&buffer),
                        }
                        buffer.clear();
                    }
                    current_tag = Some(ChangeTag::Insert);
                }
                buffer.push_str(&change.value().to_string());
            }
            ChangeTag::Delete => {
                // flush if needed? Deletions are not in output, but they separate segments? For grouping, deletion should cause flush? Actually equal/insert separated by deletions should be separate segments, but we already flush on tag change. Deletion doesn't produce output, but we should flush? Let's flush on deletion to create boundary?
                // For simplicity, if we encounter delete, flush current buffer.
                if !buffer.is_empty() {
                    match current_tag {
                        Some(ChangeTag::Equal) => out.push_str(&color_green(&buffer, true)),
                        Some(ChangeTag::Insert) => out.push_str(&color_red_bold(&buffer, true)),
                        _ => out.push_str(&buffer),
                    }
                    buffer.clear();
                    current_tag = None;
                }
            }
        }
    }
    if !buffer.is_empty() {
        match current_tag {
            Some(ChangeTag::Equal) => out.push_str(&color_green(&buffer, true)),
            Some(ChangeTag::Insert) => out.push_str(&color_red_bold(&buffer, true)),
            _ => out.push_str(&buffer),
        }
    }
    out
}

