fn collect_files(paths: &[PathBuf], recursive: bool, max_depth: Option<usize>, include_dirs: bool, hidden: bool) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for p in paths {
        if !p.exists() {
            continue;
        }
        if p.is_file() {
            files.push(p.clone());
        } else if p.is_dir() {
            if recursive {
                let max_depth_val = max_depth.unwrap_or(usize::MAX);
                let walker = walkdir::WalkDir::new(p).max_depth(max_depth_val).follow_links(true).into_iter();
                for entry in walker {
                    if let Ok(entry) = entry {
                        let entry_path = entry.path().to_path_buf();
                        if entry_path == *p {
                            continue;
                        }
                        if !hidden {
                            // check hidden components
                            let mut skip = false;
                            for comp in entry_path.components() {
                                if let Some(os_str) = comp.as_os_str().to_str() {
                                    let s = os_str;
                                    if s.starts_with('.') && s != "." && s != ".." {
                                        // Check if this component is not the root input? For entry_path that is under p, any hidden component means skip
                                        // We need to ensure we don't skip because p itself might be hidden? But p is explicit, we already handled.
                                        // To check if hidden component is beyond p, we can check if entry_path starts with p and the hidden component is after p.
                                        // Simpler: if any component after p's components is hidden, skip.
                                        // For simplicity, skip if file name hidden or any parent hidden.
                                        // We'll just check if s starts with '.' and s != "." and s != ".." and entry_path != *p
                                        // But we need to avoid skipping if p itself contains hidden? Actually if p is ".", then "." component would be considered hidden? We excluded ".".
                                        skip = true;
                                        break;
                                    }
                                }
                            }
                            if skip {
                                continue;
                            }
                        }
                        if entry_path.is_file() {
                            files.push(entry_path);
                        } else if entry_path.is_dir() && include_dirs {
                            files.push(entry_path);
                        }
                    }
                }
                if include_dirs {
                    // include input dir itself if not "." and not "./"
                    let p_str = p.to_string_lossy();
                    if p_str != "." && p_str != "./" {
                        files.push(p.clone());
                    }
                }
            } else {
                if include_dirs {
                    files.push(p.clone());
                }
            }
        }
    }
    files
}

