fn collect_files(paths: &[PathBuf], recursive: bool, max_depth: Option<usize>, include_dirs: bool, hidden: bool) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for p in paths {
        if !p.exists() { continue; }
        if p.is_file() {
            files.push(p.clone());
        } else if p.is_dir() {
            if recursive {
                let max_depth_val = max_depth.unwrap_or(usize::MAX);
                let walker = walkdir::WalkDir::new(p).max_depth(max_depth_val).follow_links(true).into_iter();
                for entry in walker {
                    if let Ok(entry) = entry {
                        let entry_path = entry.path().to_path_buf();
                        if entry_path == *p { continue; }
                        if !hidden {
                            let mut skip = false;
                            for comp in entry_path.components() {
                                if let Some(os_str) = comp.as_os_str().to_str() {
                                    if os_str.starts_with('.') && os_str != "." && os_str != ".." {
                                        skip = true; break;
                                    }
                                }
                            }
                            if skip { continue; }
                        }
                        if entry_path.is_file() {
                            files.push(entry_path);
                        } else if entry_path.is_dir() && include_dirs {
                            files.push(entry_path);
                        }
                    }
                }
                if include_dirs {
                    let p_str = p.to_string_lossy();
                    if p_str != "." && p_str != "./" {
                        files.push(p.clone());
                    }
                }
            } else {
                if include_dirs { files.push(p.clone()); }
            }
        }
    }
    files
}

