fn should_use_color(mode: &ColorMode) -> bool {
    match mode {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Auto => std::io::IsTerminal::is_terminal(&std::io::stdout()),
    }
}
fn print_dry_run_header(silent: bool, use_color: bool) {
    if silent { return; }
    if use_color {
