fn deunicode(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        if ch.is_ascii() { out.push(ch); }
        else {
            if let Some(m) = deunicode_char(ch) { out.push_str(&m); }
            else { out.push(ch); }
        }
    }
    out
}
fn ascii_transform(name: &str) -> Option<String> {
    let ascii = deunicode(name);
    if ascii == name { None } else { Some(ascii) }
}
fn apply_regex(old_name: &str, regex: &Regex, replacement: &str, limit: usize, transform: Option<&Transform>) -> Option<String> {
    let new_name = if limit == 0 {
        regex.replace_all(old_name, replacement).to_string()
    } else if limit == 1 {
        regex.replace(old_name, replacement).to_string()
    } else {
        regex.replacen(old_name, limit, replacement).to_string()
    };
    if new_name == old_name { return None; }
    let transformed = if let Some(t) = transform {
        match t {
            Transform::Upper => new_name.to_uppercase(),
            Transform::Lower => new_name.to_lowercase(),
            Transform::Ascii => deunicode(&new_name),
        }
    } else { new_name };
    if transformed == old_name { None } else { Some(transformed) }
}
fn compute_target_colored_grouped(old: &str, new: &str, _use_color: bool) -> String {
    let mut out = String::new();
    let mut last_tag = None;
    let mut buffer = String::new();
    for d in diff::chars(old, new) {
        match d {
            diff::Result::Both(c, _) => {
                if last_tag != Some(0) {
                    if !buffer.is_empty() {
                        match last_tag {
                            Some(0) => out.push_str(&format!("\x1b[32m{}\x1b[0m", buffer)),
                            Some(1) => out.push_str(&format!("\x1b[1;31m{}\x1b[0m", buffer)),
                            _ => out.push_str(&buffer),
                        }
                        buffer.clear();
                    }
                    last_tag = Some(0);
                }
                buffer.push(c);
            }
            diff::Result::Right(c) => {
                if last_tag != Some(1) {
                    if !buffer.is_empty() {
                        match last_tag {
                            Some(0) => out.push_str(&format!("\x1b[32m{}\x1b[0m", buffer)),
                            Some(1) => out.push_str(&format!("\x1b[1;31m{}\x1b[0m", buffer)),
                            _ => out.push_str(&buffer),
                        }
                        buffer.clear();
                    }
                    last_tag = Some(1);
                }
                buffer.push(c);
            }
            diff::Result::Left(_) => {
                if !buffer.is_empty() {
                    match last_tag {
                        Some(0) => out.push_str(&format!("\x1b[32m{}\x1b[0m", buffer)),
                        Some(1) => out.push_str(&format!("\x1b[1;31m{}\x1b[0m", buffer)),
                        _ => out.push_str(&buffer),
                    }
                    buffer.clear();
                    last_tag = None;
                }
            }
        }
    }
    if !buffer.is_empty() {
        match last_tag {
            Some(0) => out.push_str(&format!("\x1b[32m{}\x1b[0m", buffer)),
            Some(1) => out.push_str(&format!("\x1b[1;31m{}\x1b[0m", buffer)),
            _ => out.push_str(&buffer),
        }
    }
    out
}
fn print_operation(source: &str, target: &str, old_name: &str, new_name: &str, silent: bool, use_color: bool) {
    if silent { return; }
    if use_color {
        let source_colored = format!("\x1b[38;5;8m{}\x1b[0m", source);
        let source_path = Path::new(source);
        let colored_target = if let Some(p) = source_path.parent() {
            if !p.as_os_str().is_empty() {
                let parent_str = format!("{}/", p.display());
                let parent_colored = format!("\x1b[32m{}\x1b[0m", parent_str);
                let file_diff = compute_target_colored_grouped(old_name, new_name, true);
                format!("{}{}", parent_colored, file_diff)
            } else {
                compute_target_colored_grouped(old_name, new_name, true)
            }
        } else {
            compute_target_colored_grouped(old_name, new_name, true)
        };
        println!("{} -> {}", source_colored, colored_target);
    } else {
        println!("{} -> {}", source, target);
    }
}
fn main() {
    let cli = build_cli().get_matches();
    match cli.subcommand() {
        Some(("regex", sub_m)) => {
            let expression = sub_m.get_one::<String>("expression").unwrap().clone();
            let replacement = sub_m.get_one::<String>("replacement").unwrap().clone();
            let paths: Vec<PathBuf> = sub_m.get_many::<PathBuf>("paths").unwrap().cloned().collect();
            let common = common_args_from_matches(sub_m);
            let replace_limit = sub_m.get_one::<usize>("replace-limit").cloned();
            let rt_str = sub_m.get_one::<String>("replace-transform").map(|s| s.as_str());
            let replace_transform = rt_str.map(|s| parse_transform(s));
            let include_dirs = sub_m.get_flag("include-dirs");
            let recursive = sub_m.get_flag("recursive");
            let max_depth = sub_m.get_one::<usize>("max-depth").cloned();
            let hidden = sub_m.get_flag("hidden");
            let args = RegexArgs { expression, replacement, paths, common, replace_limit, replace_transform, include_dirs, recursive, max_depth, hidden };
            handle_regex(args);
        }
        Some(("from-file", sub_m)) => {
            let dumpfile = sub_m.get_one::<PathBuf>("dumpfile").unwrap().clone();
            let common = common_args_from_matches(sub_m);
            let undo = sub_m.get_flag("undo");
            let args = FromFileArgs { dumpfile, common, undo };
            handle_from_file(args);
        }
        Some(("to-ascii", sub_m)) => {
            let paths: Vec<PathBuf> = sub_m.get_many::<PathBuf>("paths").unwrap().cloned().collect();
            let common = common_args_from_matches(sub_m);
            let include_dirs = sub_m.get_flag("include-dirs");
            let recursive = sub_m.get_flag("recursive");
            let max_depth = sub_m.get_one::<usize>("max-depth").cloned();
            let hidden = sub_m.get_flag("hidden");
            let args = ToAsciiArgs { paths, common, include_dirs, recursive, max_depth, hidden };
            handle_to_ascii(args);
        }
        _ => {}
    }
}

fn handle_regex(args: RegexArgs) {
    let use_color = should_use_color(&args.common.color);
    let silent = args.common.silent;
    let regex = match Regex::new(&args.expression) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: Bad expression provided\n\nregex parse error:\n    {}\n    ^\nerror: {}", args.expression, e);
            std::process::exit(1);
        }
    };
    let limit = args.replace_limit.unwrap_or(1);
    let files = collect_files(&args.paths, args.recursive, args.max_depth, args.include_dirs, args.hidden);
    let mut ops: Vec<RenameOp> = Vec::new();
    for fp in files {
        let old_name = match fp.file_name().and_then(|s| s.to_str()) { Some(n) => n.to_string(), None => continue, };
        if let Some(new_name) = apply_regex(&old_name, &regex, &args.replacement, limit, args.replace_transform.as_ref()) {
            let parent = fp.parent().unwrap_or_else(|| Path::new(""));
            let target = parent.join(&new_name);
            ops.push(RenameOp { source: fp, target, old_name, new_name });
        }
    }
    let is_dry_run = !args.common.force;
    if is_dry_run { print_dry_run_header(silent, use_color); }
    for op in &ops {
        if op.target.exists() && op.source != op.target {
            if use_color {
                eprintln!("{}Conflict with existing path {}", "\x1b[31mError: \x1b[0m", format!("\x1b[31m{} -> {}\x1b[0m", op.source.display(), op.target.display()));
            } else {
                eprintln!("Error: Conflict with existing path {} -> {}", op.source.display(), op.target.display());
            }
            std::process::exit(1);
        }
    }
    {
        use std::collections::HashMap;
        let mut map: HashMap<PathBuf, Vec<&RenameOp>> = HashMap::new();
        for op in &ops { map.entry(op.target.clone()).or_default().push(op); }
        for (_, srcs) in map {
            if srcs.len() > 1 {
                if use_color {
                    eprintln!("{}Files will have the same name", "\x1b[31mError: \x1b[0m");
                    eprintln!("\x1b[31m\x1b[31m");
                    for s in srcs { eprintln!("\x1b[31m{}->{}\x1b[0m", s.source.display(), s.target.display()); }
                    eprintln!("\x1b[0m\x1b[0m");
                } else {
                    eprintln!("Error: Files will have the same name\n");
                    for s in &srcs { eprintln!("{}->{}", s.source.display(), s.target.display()); }
                    eprintln!("");
                }
                std::process::exit(1);
            }
        }
    }
    ops.sort_by(|a,b| b.source.components().count().cmp(&a.source.components().count()));
    for op in &ops {
        if args.common.backup && args.common.force {
            match backup_file(&op.source) {
                Ok(bp) => {
                    if !silent {
                        if use_color {
                            println!("{}Backup created - {}", "\x1b[1mInfo: \x1b[0m", format!("\x1b[38;5;8m{} -> {}\x1b[0m", op.source.display(), bp.display()));
                        } else {
                            println!("Info:  Backup created - {} -> {}", op.source.display(), bp.display());
                        }
                    }
                }
                Err(e) => { eprintln!("Error: Cannot create backup {}: {}", op.source.display(), e); std::process::exit(1); }
            }
        }
        print_operation(&op.source.to_string_lossy(), &op.target.to_string_lossy(), &op.old_name, &op.new_name, silent, use_color);
        if args.common.force {
            if let Err(_) = fs::rename(&op.source, &op.target) {
                eprintln!("Error: Cannot rename {} -> {}\nNo such file or directory (os error 2)", op.source.display(), op.target.display());
                std::process::exit(1);
            }
        }
    }
    let should_dump = if args.common.no_dump { false } else if args.common.dump { true } else if args.common.force { true } else { false };
    if should_dump && !ops.is_empty() {
        let date = Local::now();
        let date_str = date.format("%Y-%m-%d %H:%M:%S").to_string();
        let file_date_str = date.format("%Y-%m-%d_%H%M%S").to_string();
        let dump_filename = format!("{}{}.json", args.common.dump_prefix, file_date_str);
        let dump_ops: Vec<Operation> = ops.iter().map(|op| Operation { source: op.source.to_string_lossy().to_string(), target: op.target.to_string_lossy().to_string() }).collect();
        let dump = DumpFile { date: date_str, operations: dump_ops };
        let json = serde_json::to_string_pretty(&dump).unwrap();
        let _ = fs::write(&dump_filename, json);
    }
}

fn handle_to_ascii(args: ToAsciiArgs) {
    let use_color = should_use_color(&args.common.color);
    let silent = args.common.silent;
    let files = collect_files(&args.paths, args.recursive, args.max_depth, args.include_dirs, args.hidden);
    let mut ops: Vec<RenameOp> = Vec::new();
    for fp in files {
        let old_name = match fp.file_name().and_then(|s| s.to_str()) { Some(n) => n.to_string(), None => continue, };
        if let Some(new_name) = ascii_transform(&old_name) {
            let parent = fp.parent().unwrap_or_else(|| Path::new(""));
            let target = parent.join(&new_name);
            ops.push(RenameOp { source: fp, target, old_name, new_name });
        }
    }
    let is_dry_run = !args.common.force;
