use std::path::{Path, PathBuf};
use regex::Regex;
use chrono::Local;
use serde::{Serialize, Deserialize};
use std::fs;
use std::io::{self};
use clap::{Command, Arg, ArgAction, value_parser};

#[derive(Debug, Clone)]
enum ColorMode { Always, Never, Auto }
#[derive(Debug, Clone)]
enum Transform { Upper, Lower, Ascii }

#[derive(Serialize, Deserialize, Debug)]
struct Operation { source: String, target: String }
#[derive(Serialize, Deserialize, Debug)]
struct DumpFile { date: String, operations: Vec<Operation> }

#[derive(Debug)]
struct CommonArgs {
    dry_run: bool,
    force: bool,
    backup: bool,
    silent: bool,
    color: ColorMode,
    dump: bool,
    dump_prefix: String,
    no_dump: bool,
}
#[derive(Debug)]
struct RegexArgs {
    expression: String,
    replacement: String,
    paths: Vec<PathBuf>,
    common: CommonArgs,
    replace_limit: Option<usize>,
    replace_transform: Option<Transform>,
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
}
#[derive(Debug)]
struct ToAsciiArgs {
    paths: Vec<PathBuf>,
    common: CommonArgs,
    include_dirs: bool,
    recursive: bool,
    max_depth: Option<usize>,
    hidden: bool,
}
#[derive(Debug)]
struct FromFileArgs {
    dumpfile: PathBuf,
    common: CommonArgs,
    undo: bool,
}

fn parse_color(s: &str) -> ColorMode {
    match s {
        "always" => ColorMode::Always,
        "never" => ColorMode::Never,
        "auto" => ColorMode::Auto,
        _ => ColorMode::Auto,
    }
}
fn parse_transform(s: &str) -> Transform {
    match s {
        "upper" => Transform::Upper,
        "lower" => Transform::Lower,
        "ascii" => Transform::Ascii,
        _ => Transform::Upper,
    }
}

fn common_args_from_matches(m: &clap::ArgMatches) -> CommonArgs {
    let dry_run = m.get_flag("dry-run");
    let force = m.get_flag("force");
    let backup = m.get_flag("backup");
    let silent = m.get_flag("silent");
    let color_str = m.get_one::<String>("color").map(|s| s.as_str()).unwrap_or("auto");
    let color = parse_color(color_str);
    let dump = m.get_flag("dump");
    let dump_prefix = m.get_one::<String>("dump-prefix").cloned().unwrap_or_else(|| "rnr-".to_string());
    let no_dump = m.get_flag("no-dump");
    CommonArgs { dry_run, force, backup, silent, color, dump, dump_prefix, no_dump }
}

fn build_cli() -> Command {
    Command::new("executable")
        .version("0.5.1")
        .about("RnR is a command-line tool to rename multiple files and directories that\nsupports regular expressions")
        .subcommand_required(true)
        .subcommand(
            Command::new("regex")
                .about("Rename files and directories using a regular expression")
                .arg(Arg::new("expression").help("Expression to match (can be a regex)").required(true))
                .arg(Arg::new("replacement").help("Expression replacement (use single quotes for capture groups)").required(true))
                .arg(Arg::new("paths").help("Target paths").required(true).num_args(1..).value_parser(value_parser!(PathBuf)))
                .arg(Arg::new("dry-run").short('n').long("dry-run").help("Only show what would be done (default mode)").action(ArgAction::SetTrue).conflicts_with("force"))
                .arg(Arg::new("force").short('f').long("force").help("Make actual changes to files").action(ArgAction::SetTrue).conflicts_with("dry-run"))
                .arg(Arg::new("backup").short('b').long("backup").help("Generate file backups before renaming").action(ArgAction::SetTrue))
                .arg(Arg::new("silent").short('s').long("silent").help("Do not print any information").action(ArgAction::SetTrue))
                .arg(Arg::new("color").long("color").help("Set color output mode").default_value("auto").value_parser(["always","never","auto"]))
                .arg(Arg::new("dump").long("dump").help("Force dumping operations into a file even in dry-run mode").action(ArgAction::SetTrue).conflicts_with("no-dump"))
                .arg(Arg::new("dump-prefix").long("dump-prefix").help("Set the dump file prefix").default_value("rnr-"))
                .arg(Arg::new("no-dump").long("no-dump").help("Do not dump operations into a file").action(ArgAction::SetTrue).conflicts_with("dump"))
