fn handle_from_file(args: FromFileArgs) {
    let use_color = should_use_color(&args.common.color);
    let silent = args.common.silent;
    let content = match fs::read_to_string(&args.dumpfile) {
        Ok(c) => c,
        Err(_) => {
            if !args.common.force { print_dry_run_header(silent, use_color); }
            if use_color {
                eprintln!("{}Cannot open/read file {}", "\x1b[31mError: \x1b[0m", format!("\x1b[31m{}\x1b[0m", args.dumpfile.display()));
            } else {
                eprintln!("Error: Cannot open/read file {}", args.dumpfile.display());
            }
            std::process::exit(1);
        }
    };
    let dump: DumpFile = match serde_json::from_str(&content) {
        Ok(d) => d,
        Err(_) => {
            if !args.common.force { print_dry_run_header(silent, use_color); }
            if use_color {
                eprintln!("{}Cannot parse JSON file {}", "\x1b[31mError: \x1b[0m", args.dumpfile.display());
